import pandas as pd
import numpy as np

def audit_data(df):
    missing_counts = df.isnull().sum()
    missing_fraction = missing_counts / len(df)
    high_missing_cols = missing_fraction[missing_fraction > 0.30].index.tolist()
    return {
        'missing_counts': missing_counts,
        'high_missing_cols': high_missing_cols,
    }

import numpy as np

def ensemble_models(classifiers, X_train, y_train, X_test):
    all_probas = []
    for clf in classifiers:
        clf.fit(X_train, y_train)
        proba = clf.predict_proba(X_test)
        all_probas.append(proba)
    avg_proba = np.mean(all_probas, axis=0)
    predictions = np.argmax(avg_proba, axis=1)
    return (avg_proba, predictions)
